cat > providers.tf <<'EOF'
provider "aws" {
  region = "eu-north-1"
}
EOF
cat > variables.tf <<'EOF'
variable "github_repository" {
  type        = string
  description = "GitHub repository, as owner/name, whose workflows may assume the CI roles. The OIDC subject claim is matched against this exact value."
  default     = "platform/ingest"

  validation {
    condition     = can(regex("^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$", var.github_repository))
    error_message = "github_repository must be in owner/name form with no wildcards."
  }
}

variable "apply_branch" {
  type        = string
  description = "Branch whose workflow runs may assume the apply role. Runs from any other ref are refused by the role's trust policy."
  default     = "main"
}

variable "state_bucket" {
  type        = string
  description = "Name of the S3 bucket holding the ingest configuration's Terraform state."
  default     = "ingest-terraform-state"
}

variable "state_key" {
  type        = string
  description = "Object key of the ingest configuration's state file in the state bucket."
  default     = "ingest/terraform.tfstate"
}

variable "bucket_names" {
  type        = list(string)
  description = "Names of the S3 buckets the ingest configuration manages. The CI roles are granted access to these buckets only."
  default     = ["ingest-landing-staging"]
}

variable "queue_names" {
  type        = list(string)
  description = "Names of the SQS queues the ingest configuration manages. The CI roles are granted access to these queues only."
  default     = ["ingest-events-staging"]
}

variable "table_names" {
  type        = list(string)
  description = "Names of the DynamoDB tables the ingest configuration manages. The CI roles are granted access to these tables only."
  default     = ["ingest-checkpoints-staging"]
}

variable "max_session_duration" {
  type        = number
  description = "Maximum lifetime in seconds of a session obtained by assuming either CI role."
  default     = 3600

  validation {
    condition     = var.max_session_duration >= 3600 && var.max_session_duration <= 43200
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }
}
EOF
cat > main.tf <<'EOF'
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region

  oidc_host = "token.actions.githubusercontent.com"

  bucket_arns = [for n in var.bucket_names : "arn:aws:s3:::${n}"]
  queue_arns  = [for n in var.queue_names : "arn:aws:sqs:${local.region}:${local.account_id}:${n}"]
  table_arns  = [for n in var.table_names : "arn:aws:dynamodb:${local.region}:${local.account_id}:table/${n}"]

  state_object_arn = "arn:aws:s3:::${var.state_bucket}/${var.state_key}"
  state_lock_arn   = "arn:aws:s3:::${var.state_bucket}/${var.state_key}.tflock"
  state_bucket_arn = "arn:aws:s3:::${var.state_bucket}"
}

# One provider per account per issuer URL. If the account already has one, import it
# instead of creating a second.
resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://${local.oidc_host}"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_host}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_host}:sub"
      values   = ["repo:${var.github_repository}:pull_request"]
    }
  }
}

data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_host}:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "${local.oidc_host}:sub"
      values   = ["repo:${var.github_repository}:ref:refs/heads/${var.apply_branch}"]
    }
  }
}

# Read access to the managed resources, used to refresh state and compute a diff.
data "aws_iam_policy_document" "read" {
  statement {
    sid       = "ReadBuckets"
    actions   = ["s3:GetBucketLocation", "s3:ListBucket", "s3:Get*"]
    resources = local.bucket_arns
  }

  statement {
    sid       = "ReadQueues"
    actions   = ["sqs:GetQueueAttributes", "sqs:GetQueueUrl", "sqs:ListQueueTags"]
    resources = local.queue_arns
  }

  statement {
    sid = "ReadTables"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = local.table_arns
  }

  statement {
    sid       = "ReadState"
    actions   = ["s3:GetObject"]
    resources = [local.state_object_arn]
  }

  statement {
    sid       = "ListStateBucket"
    actions   = ["s3:ListBucket"]
    resources = [local.state_bucket_arn]

    condition {
      test     = "StringEquals"
      variable = "s3:prefix"
      values   = [var.state_key]
    }
  }

  # use_lockfile writes and removes a lock object next to the state file, so even a
  # plan needs this. It cannot modify the state object itself.
  statement {
    sid       = "HoldStateLock"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = [local.state_lock_arn]
  }
}

data "aws_iam_policy_document" "write" {
  statement {
    sid = "ManageBuckets"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:PutBucket*",
      "s3:PutEncryptionConfiguration",
      "s3:PutLifecycleConfiguration",
      "s3:PutAccelerateConfiguration",
      "s3:PutReplicationConfiguration",
    ]
    resources = local.bucket_arns
  }

  statement {
    sid = "ManageQueues"
    actions = [
      "sqs:CreateQueue",
      "sqs:DeleteQueue",
      "sqs:SetQueueAttributes",
      "sqs:TagQueue",
      "sqs:UntagQueue",
    ]
    resources = local.queue_arns
  }

  statement {
    sid = "ManageTables"
    actions = [
      "dynamodb:CreateTable",
      "dynamodb:DeleteTable",
      "dynamodb:UpdateTable",
      "dynamodb:UpdateContinuousBackups",
      "dynamodb:UpdateTimeToLive",
      "dynamodb:TagResource",
      "dynamodb:UntagResource",
    ]
    resources = local.table_arns
  }

  statement {
    sid       = "WriteState"
    actions   = ["s3:PutObject"]
    resources = [local.state_object_arn]
  }
}

resource "aws_iam_role" "plan" {
  name                 = "ingest-ci-plan"
  description          = "Assumed by pull_request runs of the ingest workflow to run terraform plan. Read-only on managed resources."
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = var.max_session_duration
}

resource "aws_iam_role_policy" "plan" {
  name   = "plan"
  role   = aws_iam_role.plan.id
  policy = data.aws_iam_policy_document.read.json
}

resource "aws_iam_role" "apply" {
  name                 = "ingest-ci-apply"
  description          = "Assumed by runs of the ingest workflow on the apply branch to run terraform apply, scoped to the ingest resources."
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = var.max_session_duration
}

resource "aws_iam_role_policy" "apply_read" {
  name   = "read"
  role   = aws_iam_role.apply.id
  policy = data.aws_iam_policy_document.read.json
}

resource "aws_iam_role_policy" "apply_write" {
  name   = "write"
  role   = aws_iam_role.apply.id
  policy = data.aws_iam_policy_document.write.json
}
EOF
cat > outputs.tf <<'EOF'
output "plan_role_arn" {
  description = "ARN of the read-only role for the workflow's pull_request plan job."
  value       = aws_iam_role.plan.arn
}

output "apply_role_arn" {
  description = "ARN of the role for the workflow's apply job on the apply branch."
  value       = aws_iam_role.apply.arn
}
EOF
cat > README.md <<'EOF'
# ci-identity

AWS side of the CI handover described in the repository README: the GitHub OIDC provider and two
roles for the `platform/ingest` workflow. It has its own state key and is applied by an
administrator, not by the workflow, so the CI roles cannot modify their own permissions.

| Role | Assumable from | Grants |
|---|---|---|
| `ingest-ci-plan` | `pull_request` runs | Read on the managed bucket, queue and table; read of the state object; the state lock object |
| `ingest-ci-apply` | runs on `refs/heads/main` | The plan permissions, plus create, update and delete on the managed bucket, queue and table, and write of the state object |

Both trust policies match the token `aud` and an exact `sub`; there are no wildcards.

## Workflow requirements

- Job permissions: `id-token: write` and `contents: read`.
- Use `aws-actions/configure-aws-credentials`, pinned by commit SHA, with `role-to-assume` set to
  the matching output.
- Run `plan` on `pull_request` with the plan role, and `apply` on `push` to `main` with the apply
  role. Pull requests from forks do not receive an OIDC token.
- Add a GitHub environment with required reviewers to the apply job if approval is wanted. Then
  change the apply role's `sub` to match `repo:<owner>/<name>:environment:<name>`.

## Adding resources

When the ingest configuration gains a resource of a new type, add its actions here. A plan that
fails with `AccessDenied` shows which are missing.

## Existing OIDC provider

An account holds one provider per issuer URL. If `token.actions.githubusercontent.com` already
exists, run `terraform import aws_iam_openid_connect_provider.github <arn>` before applying.
EOF
